def compteNiveau(A, k):
    """Nombre de nœuds de profondeur k dans A."""
    if A is None:
        return 0
    if k == 0:
        return 1
    return compteNiveau(A.gauche, k - 1) + compteNiveau(A.droite, k - 1)


def LCparNiveaux(A):
    return sum(k * compteNiveau(A, k) for k in range(hauteur(A) + 1))


